    init_C(j, i) = cast<num_t>(((i + j) % 100)) / cast<int>(m);
    init_B(j, i) = cast<num_t>(((n + i - j) % 100)) / cast<int>(m);

    // Initialize A (lower triangular part contains data; upper part is -999):
    //
    // for (i = 0; i < m; i++) {
    //   for (j = 0; j <= i; j++)
    //       A[i][j] = (DATA_TYPE)((i + j) % 100) / m;
    //   for (j = i+1; j < m; j++)
    //       A[i][j] = -999;
    // }
