    // - j (dim 0) is contiguous in memory, so we vectorize over j.
    // - i (dim 1) is outer, so we parallelize over i.
    init_C
        .parallel(i)
        .vectorize(j, vec_width);

    init_B
        .parallel(i)
        .vectorize(j, vec_width);

    init_A
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize into the provided buffers
    init_C.realize(C);
    init_B.realize(B);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size (from symm.hpp / defines.hpp)
    int m = M;
    int n = N;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    //   C, B : MxN  -> (n, m) in Halide (dim 0 = columns j, dim 1 = rows i)
    //   A    : MxM  -> (m, m) in Halide
    Halide::Buffer<num_t, 2> C(n, m);
    Halide::Buffer<num_t, 2> B(n, m);
    Halide::Buffer<num_t, 2> A(m, m);

    // ImageParams to pass the buffers into the Halide pipeline
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam B_param(type_of<num_t>(), 2, "B_param");

    // Initialize data
    init_array(m, n, &alpha, &beta, C, A, B);

    // Vars and reduction domain
    Var i("i"), j("j");
    // A is MxM stored as A(j, i); extent of dim(0) is m
    RDom k(0, A.dim(0).extent(), "k");

    // Main computational kernel in Halide.
    //
    // Original BLAS semantics:
    //   C := alpha * A * B + beta * C
    // with A symmetric, stored in its lower triangular part.
    //
    // We construct a symmetric view of A:
    //   A_sym(i, l) =
    //      (l <= i) ? A(i, l)  : A(l, i)
    //
    // Remember our Buffer mapping:
    //   original A[i][l] -> A_param(l, i)
    //   original A[l][i] -> A_param(i, l)
    //
    // So we define:
    //   A_sym(i, k) = (k <= i) ? A_param(k, i) : A_param(i, k)
    //
    // Then:
    //   symm(j, i) = beta * C_param(j, i)
    //   symm(j, i) += alpha * sum_k A_sym(i, k) * B_param(j, k)
    //
    Func symm("symm");

    Expr alpha_expr = Expr(alpha);
    Expr beta_expr  = Expr(beta);

    // Base: beta * C
    symm(j, i) = beta_expr * C_param(j, i);

    // Symmetric access to A
    Expr A_sym = select(k <= i, A_param(k, i), A_param(i, k));

    // Accumulate alpha * A_sym * B
    symm(j, i) += alpha_expr * A_sym * B_param(j, k);

    // --------------------------------------------------------------------
    // Optimized schedule for symm:
    //
    // Layout recap:
    //   - C, B: Buffer(j, i) with j contiguous in memory.
    //   - We want to vectorize across j and tile (i, j) for cache locality.
    //   - Parallelism across tiles; reduction over k remains serial per (i, j).
    // --------------------------------------------------------------------
    Target target = get_jit_target_from_environment();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    Var jo("jo"), io("io"), ji("ji"), ii("ii"), tile_index("tile_index");

    // Tile the output domain in (j, i):
    //   - 64 columns (j) x 32 rows (i) per tile is a reasonable default.
    //   - Fuse the tile coordinates and parallelize across tiles.
    //   - Vectorize across ji (the inner j dimension) to exploit SIMD on
    //     contiguous memory.
    symm
        .tile(j, i, jo, io, ji, ii, 64, 32)
        .fuse(jo, io, tile_index)
        .parallel(tile_index)
        .vectorize(ji, vec_width);

    // For the reduction update:
    //   - Keep the same tiling structure (tile_index, ii, ji).
    //   - Make ji innermost for contiguous access to C and B.
    //   - Put k just outside ji so that for each k we do a tight, vectorized
    //     inner product over columns.
    symm.update()
        .reorder(ji, k, ii, tile_index)  // inner -> outer: ji, k, ii, tile_index
        .vectorize(ji, vec_width);

    // Bind buffers to ImageParams
    C_param.set(C);
    A_param.set(A);
    B_param.set(B);

    // JIT-compile the kernel with the chosen target
    symm.compile_jit(target);

    // Time the kernel
    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result back into C
    symm.realize(C);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (mainly to prevent dead-code elimination),
    // following the style of the GEMM example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < m; ii++) {
            for (int jj = 0; jj < n; jj++) {
